  const content=mount.querySelector('#c-content'),back=mount.querySelector('#c-back'),currentSlot=mount.querySelector('#c-current'),globalSearch=mount.querySelector('#c-global-search'),noticeEl=mount.querySelector('#c-notice');let noticeTimer;
